from contextlib import asynccontextmanager
from fastapi import FastAPI
def create_app():
    @asynccontextmanager
    async def lifespan(app):
        resource = await open_resource()
        try:
            yield resource
        finally:
            await resource.close()
    return FastAPI(lifespan=lifespan)

